#!/usr/bin/env node
/**
 * Warung OS — Phase 5 local hosted-mirror export prep
 *
 * This script does NOT upload, deploy, or contact Supabase/Vercel.
 * It prepares a sanitized local export package that can later be uploaded by
 * a separate publisher after Raz confirms hosting/auth details.
 *
 * Input:  public/snapshots/latest.json (generated by npm run snapshot:generate)
 * Output: hosted-export/latest.json + hosted-export/manifest.json (gitignored)
 */

import { createHash } from 'node:crypto'
import { existsSync, mkdirSync, readFileSync, writeFileSync } from 'node:fs'
import { dirname, join } from 'node:path'
import { fileURLToPath } from 'node:url'

const __dirname = dirname(fileURLToPath(import.meta.url))
const ROOT = join(__dirname, '..')
const SNAPSHOT_FILE = join(ROOT, 'public', 'snapshots', 'latest.json')
const EXPORT_DIR = join(ROOT, 'hosted-export')
const EXPORT_FILE = join(EXPORT_DIR, 'latest.json')
const MANIFEST_FILE = join(EXPORT_DIR, 'manifest.json')
const DEFAULT_MAX_AGE_MINUTES = 60

const SECRET_VALUE_PATTERNS = [
  /sk-[A-Za-z0-9_-]{20,}/,
  /ghp_[A-Za-z0-9_]{20,}/,
  /github_pat_[A-Za-z0-9_]{20,}/,
  /xox[abprs]-[A-Za-z0-9-]{20,}/,
  /SUPABASE_SERVICE_ROLE_KEY/i,
  /service[_-]?role/i,
  /-----BEGIN [A-Z ]*PRIVATE KEY-----/,
]

const ABSOLUTE_PATH_PATTERN = /(?:\/Users\/|\/var\/folders\/|\/Volumes\/|[A-Za-z]:\\)/

function isSensitiveKey(key) {
  const normalized = key.toLowerCase().replace(/[^a-z0-9]/g, '_')

  // Allowed telemetry/count keys — these are aggregate token usage metrics, not credentials.
  if (
    normalized.endsWith('_tokens') ||
    normalized === 'total_tokens' ||
    normalized === 'input_tokens' ||
    normalized === 'output_tokens' ||
    normalized === 'cache_read_tokens' ||
    normalized === 'cache_write_tokens' ||
    normalized === 'agent_token_daily' ||
    normalized === 'model_token_daily'
  ) {
    return false
  }

  return [
    'api_key',
    'access_token',
    'refresh_token',
    'id_token',
    'session_token',
    'service_role_key',
    'service_role',
    'private_key',
    'client_secret',
    'password',
    'oauth',
    'credential',
    'credentials',
    'chat_id',
    'delivery_target',
    'prompt',
    'raw_prompt',
    'transcript',
    'raw_transcript',
    'memory_dump',
  ].some((blocked) => normalized.includes(blocked))
}

function walk(value, path = [], issues = []) {
  if (Array.isArray(value)) {
    value.forEach((item, index) => walk(item, [...path, String(index)], issues))
    return issues
  }

  if (value && typeof value === 'object') {
    for (const [key, child] of Object.entries(value)) {
      const childPath = [...path, key]
      if (isSensitiveKey(key)) {
        issues.push({ path: childPath.join('.'), reason: `sensitive key name: ${key}` })
      }
      walk(child, childPath, issues)
    }
    return issues
  }

  if (typeof value === 'string') {
    if (ABSOLUTE_PATH_PATTERN.test(value)) {
      issues.push({ path: path.join('.'), reason: 'absolute local filesystem path found' })
    }
    for (const pattern of SECRET_VALUE_PATTERNS) {
      if (pattern.test(value)) {
        issues.push({ path: path.join('.'), reason: `secret-like value matched ${pattern}` })
      }
    }
  }

  return issues
}

function sha256(text) {
  return createHash('sha256').update(text).digest('hex')
}

function readSnapshot() {
  if (!existsSync(SNAPSHOT_FILE)) {
    throw new Error(`Missing ${SNAPSHOT_FILE}. Run npm run snapshot:generate first.`)
  }

  const raw = readFileSync(SNAPSHOT_FILE, 'utf8')
  return JSON.parse(raw)
}

function assertSnapshotContract(snapshot) {
  if (!snapshot || typeof snapshot !== 'object') throw new Error('Snapshot root must be an object.')
  if (!snapshot.meta || typeof snapshot.meta !== 'object') throw new Error('Snapshot meta is missing.')
  if (snapshot.meta.schema_version !== '1') throw new Error(`Unsupported schema_version: ${snapshot.meta.schema_version}`)
  if (snapshot.meta.source_mode !== 'snapshot') throw new Error(`Expected source_mode=snapshot, got ${snapshot.meta.source_mode}`)
  if (snapshot.meta.source_scope !== 'hermes-only') throw new Error(`Expected source_scope=hermes-only, got ${snapshot.meta.source_scope}`)
  if (snapshot.operations?.source_scope !== 'hermes-only') throw new Error('operations.source_scope must be hermes-only.')
  if (snapshot.meta.is_demo !== false) throw new Error('Hosted export must be prepared from a real local snapshot with is_demo=false.')
}

function main() {
  const snapshot = readSnapshot()
  assertSnapshotContract(snapshot)

  const issues = walk(snapshot)
  if (issues.length > 0) {
    const formatted = issues.map((issue) => `- ${issue.path}: ${issue.reason}`).join('\n')
    throw new Error(`Hosted export safety validation failed:\n${formatted}`)
  }

  const preparedAt = new Date().toISOString()
  const maxAgeMinutes = Number.parseInt(process.env.WARUNG_OS_HOSTED_MAX_AGE_MINUTES ?? '', 10) || DEFAULT_MAX_AGE_MINUTES

  const hostedSnapshot = {
    ...snapshot,
    meta: {
      ...snapshot.meta,
      max_age_minutes: maxAgeMinutes,
      published_at: preparedAt,
      hosted_export: {
        prepared_at: preparedAt,
        mode: 'local-export-only',
        storage_strategy: 'supabase-storage',
        upload_performed: false,
      },
    },
  }

  const payload = JSON.stringify(hostedSnapshot, null, 2)
  const manifest = {
    generated_at: preparedAt,
    source_snapshot_generated_at: snapshot.meta.generated_at,
    source_scope: snapshot.meta.source_scope,
    schema_version: snapshot.meta.schema_version,
    max_age_minutes: maxAgeMinutes,
    upload_performed: false,
    export_file: 'hosted-export/latest.json',
    sha256: sha256(payload),
    byte_size: Buffer.byteLength(payload, 'utf8'),
    counts: {
      projects: snapshot.projects?.items?.length ?? 0,
      wiki_entries: snapshot.wiki?.entries?.length ?? 0,
      cron_jobs: snapshot.operations?.cron_jobs?.length ?? 0,
      source_health: snapshot.operations?.source_health?.length ?? 0,
      sync_runs: snapshot.operations?.sync_runs?.length ?? 0,
      sync_requests: snapshot.operations?.sync_requests?.length ?? 0,
    },
    safety_checks: {
      absolute_paths: 'passed',
      secret_like_values: 'passed',
      sensitive_key_names: 'passed',
      hermes_only_scope: 'passed',
    },
  }

  mkdirSync(EXPORT_DIR, { recursive: true })
  writeFileSync(EXPORT_FILE, payload, 'utf8')
  writeFileSync(MANIFEST_FILE, JSON.stringify(manifest, null, 2), 'utf8')

  console.log(`[warung-os] Hosted mirror export prepared → ${EXPORT_FILE}`)
  console.log(`[warung-os] Manifest written → ${MANIFEST_FILE}`)
  console.log(`[warung-os] sha256: ${manifest.sha256}`)
  console.log(`[warung-os] upload_performed: false · mode: local-export-only · max_age_minutes: ${maxAgeMinutes}`)
}

try {
  main()
} catch (error) {
  console.error(`[warung-os] Hosted mirror export failed: ${error.message}`)
  process.exit(1)
}
